<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#172b4d}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.amount{text-align:right}h1{font-size:25px}</style></head><body><h1>{{ $invoice->tax_minor > 0 ? 'Tax invoice' : 'Invoice' }} {{ $invoice->number }}</h1><p>Issued {{ $invoice->issued_at->format('Y-m-d') }} · Due {{ $invoice->due_date->format('Y-m-d') }}</p><h3>{{ $invoice->supplier_snapshot['registered_name'] }}</h3><p>{{ $invoice->supplier_snapshot['billing_address'] }}<br>{{ $invoice->supplier_snapshot['contact_email'] }}<br>Registration: {{ $invoice->supplier_snapshot['registration_number'] ?? '—' }} @if($invoice->supplier_snapshot['vat_number'] ?? null)<br>VAT: {{ $invoice->supplier_snapshot['vat_number'] }}@endif</p><h3>Bill to</h3><p>{{ $invoice->customer_snapshot['billing_name'] ?? $invoice->customer_snapshot['name'] ?? '' }}<br>{{ $invoice->customer_snapshot['email'] ?? '' }}<br>{{ $invoice->customer_snapshot['phone'] ?? '' }}<br>{{ $invoice->customer_snapshot['billing_address'] ?? '' }} @if($invoice->customer_snapshot['vat_number'] ?? null)<br>VAT: {{ $invoice->customer_snapshot['vat_number'] }}@endif</p><table><thead><tr><th>Description</th><th>Quantity</th><th class="amount">Amount ({{ $invoice->currency }})</th></tr></thead><tbody>@foreach($invoice->lines as $line)<tr><td>{{ $line['description'] }}</td><td>{{ $line['quantity'] }}</td><td class="amount">{{ number_format($line['amount_minor']/100,2) }}</td></tr>@endforeach</tbody></table><p class="amount">Subtotal: {{ number_format($invoice->subtotal_minor/100,2) }}<br>Tax: {{ number_format($invoice->tax_minor/100,2) }}<br><strong>Total {{ $invoice->currency }} {{ number_format($invoice->total_minor/100,2) }}</strong></p><p>Amounts retained from the accepted quotation. Payments are recorded separately.</p></body></html>
